// Obter a data atual como objeto Date
let dataAtual = new Date();

// Configurar fuso horário para São Paulo
dataAtual = new Date(dataAtual.toLocaleString("en-US", {timeZone: 'America/Sao_Paulo'}));

// Obter hora atual
let horaAtual = dataAtual.getHours();

// Determinar a saudação adequada baseada na hora do dia
let saudacao;

if (horaAtual >= 5 && horaAtual < 12) {
  saudacao = "Bom dia!";
} else if (horaAtual >= 12 && horaAtual < 18) {
  saudacao = "Boa tarde!";
} else if (horaAtual >= 18 && horaAtual <= 23) {
  saudacao = "Boa noite!";
} else {
  saudacao = "Boa madrugada!";
}

// Definir a saudação como uma variável de contexto
return { saudacao: saudacao };

